package com.finvista.controller;
import com.finvista.config.SecurityConfig;import com.finvista.service.*;import jakarta.servlet.Filter;import org.junit.jupiter.api.*;import org.springframework.context.annotation.*;import org.springframework.mock.web.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.web.context.HttpSessionSecurityContextRepository;import org.springframework.test.web.servlet.MockMvc;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import org.springframework.web.context.support.AnnotationConfigWebApplicationContext;import org.springframework.web.servlet.config.annotation.EnableWebMvc;import java.util.List;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
class FinancialManagementAccessTest {
 AnnotationConfigWebApplicationContext context;MockMvc mvc;
 @Configuration @EnableWebMvc @EnableWebSecurity @Import({SecurityConfig.class,FinancialManagementController.class,ManagerialDreMappingController.class}) static class Config {
 @Bean com.finvista.repository.StatementMovementRepository statements(){return mock(com.finvista.repository.StatementMovementRepository.class);}@Bean StatementImportService reader(){return mock(StatementImportService.class);}
 @Bean FinancialManagementService management(){return mock(FinancialManagementService.class);}@Bean ContaAzulReconciliationService reconciliation(){return mock(ContaAzulReconciliationService.class);}@Bean ClienteContextService ctx(){var c=mock(ClienteContextService.class);when(c.getClienteAtualId()).thenReturn(7L);return c;}@Bean ManagerialDreService dre(){return mock(ManagerialDreService.class);}}
 @BeforeEach void setup(){context=new AnnotationConfigWebApplicationContext();context.setServletContext(new MockServletContext());context.register(Config.class);context.refresh();mvc=MockMvcBuilders.webAppContextSetup(context).addFilters(context.getBean("springSecurityFilterChain",Filter.class)).build();}
 @AfterEach void close(){context.close();SecurityContextHolder.clearContext();}
 MockHttpSession session(String role){var s=new MockHttpSession();var c=SecurityContextHolder.createEmptyContext();c.setAuthentication(new UsernamePasswordAuthenticationToken("usuario",null,List.of(new SimpleGrantedAuthority("ROLE_"+role))));s.setAttribute(HttpSessionSecurityContextRepository.SPRING_SECURITY_CONTEXT_KEY,c);return s;}
 @Test void healthRequiresAuthentication() throws Exception {mvc.perform(get("/api/gestao-financeira/saude")).andExpect(status().isUnauthorized());verifyNoInteractions(context.getBean(FinancialManagementService.class));}
 @Test void authenticatedClientCanReadOwnHealth() throws Exception {mvc.perform(get("/api/gestao-financeira/saude").session(session("USUARIO"))).andExpect(status().isOk());verify(context.getBean(FinancialManagementService.class)).health();}
 @Test void ownCompanyReconciliationDoesNotTakeArbitraryClientId() throws Exception {mvc.perform(get("/api/gestao-financeira/conferencia").param("clienteId","999").param("inicio","2026-09-01").param("fim","2026-09-30").session(session("USUARIO"))).andExpect(status().isOk());verify(context.getBean(ContaAzulReconciliationService.class)).conferirLeitura(7L,java.time.LocalDate.of(2026,9,1),java.time.LocalDate.of(2026,9,30));}
 @Test void invalidDateDoesNotReachService() throws Exception {mvc.perform(get("/api/gestao-financeira/dre").param("inicio","invalid").session(session("USUARIO"))).andExpect(status().isBadRequest());verifyNoInteractions(context.getBean(ManagerialDreService.class));}
 @Test void clientCannotDeleteMappings() throws Exception {mvc.perform(delete("/api/admin/gestao-financeira/dre-mapeamentos/00000000-0000-0000-0000-000000000001").param("versao","0").session(session("USUARIO"))).andExpect(status().isForbidden());verifyNoInteractions(context.getBean(ManagerialDreService.class));}
 @Test void clientCannotPostMappings() throws Exception {mvc.perform(post("/api/admin/gestao-financeira/dre-mapeamentos").contentType("application/json").content("{}").session(session("USUARIO"))).andExpect(status().isForbidden());verifyNoInteractions(context.getBean(ManagerialDreService.class));}
}
